window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5aae5d00cd13c25e"]={"versions": [{"id": "FIG-5aae5d00cd13c25e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Programmablaufplan / Aktivitätsdiagramm (Control Flow Diagram) mit Differenzierung zwischen Compile-Time- und Runtime-Entscheidungsebenen.\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Functional Cluster <code>Log and Trace</code> (<code>ara::log</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung des internen Kontroll- und Filterflusses beim Absetzen eines Log-/Trace-Aufrufs (<code>logger.Log</code>). Visualisiert wird die Verzweigung zwischen dem klassischen DLT-Pfad (Diagnostic Log and Trace, Serialisierung &amp; IPC/Sink) und der ARTI-Schnittstelle (AUTOSAR Run-Time Interface für Tracing/Profiling) unter Berücksichtigung statischer C++-Template-Spezialisierung und dynamischer Filtermasken.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Funktionseinheiten:</strong>\n<ul class=\"fig-list\"><li><code>logger.Log(msg_id, params)</code>: Öffentliche C++-API-Einstiegsfunktion des Loggers.\n</li><li><code>TraceSwitch</code>: Statische Compile-Time-Verzweigung via C++-Template-Spezialisierung.\n</li><li><code>loggerimpl.Log(msg_id, params)</code>: Interne Laufzeit-Implementierungsklasse der Logging-Engine (blauer Bereich).\n</li><li><code>TraceArti</code>: ARTI-Trace-Hook / Backend-Schnittstelle zur Erfassung von Timing- und Laufzeitdaten ohne vorherige DLT-Filterung.\n</li><li><code>buildDltMessage()</code>: Serialisierungs-Engine zur Generierung der standardisierten DLT-Nachrichtenstruktur (Standard/Extended Header, Payload).\n</li><li><code>sendDltMessageToSink()</code>: IPC-/Transport-Abstraktion zum Versenden der DLT-PDU an den DLT-Daemon oder direkt an eine konfigurierte Log-Senke (z. B. Konsole, Dateisystem, Netzwerk/SOME/IP).\n</li><li><code>end</code>: Terminierung des Logging-Aufrufs.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Kontrollvariablen:</strong>\n<ul class=\"fig-list\"><li><code>msg_id</code>: Nachrichtenidentifikator, enthält u. a. das Bitfeld <code>mstp_mtin</code> (DLT Message Type &amp; Message Type Info: Log-Level bzw. Trace-Subtyp).\n</li><li><code>params</code>: Variadische Nutzdaten / Log-Argumente.\n</li><li><code>logTraceLogMode</code>: Laufzeit-Betriebsmodus der Logging-Instanz (Gegenprüfung auf Enumerator <code>kARTI</code>).\n</li><li><code>logmask</code>: Konfigurierte Bitmaske der aktiven Log-Level bzw. Trace-Typen.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>API-Aufruf (Synchron):</strong> Die Applikation ruft <code>logger.Log(msg_id, params)</code> auf.\n</li><li><strong>Compile-Time-Evaluation (<code>TraceSwitch</code>):</strong>\n<ul class=\"fig-list\"><li><em>Zweig „No“:</em> Direkte Ausleitung an <code>TraceArti</code>. Umgeht zur Compile-Zeit die Laufzeit-Logger-Engine vollständig (Zero-Overhead-Pfad).\n</li><li><em>Zweig „Yes“:</em> Weiterleitung an die Laufzeit-Instanz <code>loggerimpl.Log(msg_id, params)</code>.\n</li></ul>\n</li><li><strong>Evaluation Logging-Modus (<code>kARTI == logTraceLogMode?</code>):</strong>\n<ul class=\"fig-list\"><li><em>Zweig „Yes“:</em> Verzweigt vor der DLT-Filterung direkt zu <code>TraceArti</code>. Die Filterung erfolgt in ARTI autonom auf Basis der <code>msg_id</code>.\n</li><li><em>Zweig „No“:</em> Eintritt in die DLT-Verarbeitungskette.\n</li></ul>\n</li><li><strong>DLT-Laufzeit-Filterung:</strong>\n<ul class=\"fig-list\"><li>Bedingung: <code>(0 == msg_id.mstp_mtin &amp; logmask)</code>\n</li><li><em>Evaluation <code>true</code> (Ergebnis 0):</em> Die Nachricht ist durch die Bitmaske maskiert/inaktiv → Sprung zu <code>end</code> (Drop/Frühzeitiger Abbruch ohne Payload-Generierung).\n</li><li><em>Evaluation <code>false</code> (Schnittmenge vorhanden):</em> Die Nachricht ist aktiv.\n</li></ul>\n</li><li><strong>Nachrichtenkonstruktion &amp; Dispatch:</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>buildDltMessage()</code> zur Formatierung der DLT-Frames.\n</li><li>Aufruf von <code>sendDltMessageToSink()</code> zur Weiterleitung an das Backend.\n</li><li>Terminierung bei <code>end</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Compile-Time-Optimierung (<code>TraceSwitch</code>):</strong> Durch Template-Spezialisierung kann der Trace-Pfad deterministisch fest verdrahtet werden. Entwickler müssen sicherstellen, dass bei aktivierten Low-Overhead-Traces keine unnötige Instanziierung von <code>loggerimpl</code> erfolgt.\n</li><li><strong>Separater ARTI-Filterpfad:</strong> ARTI-Meldungen dürfen <strong>nicht</strong> durch die DLT-Logmaske gefiltert werden. Das DLT-Laufzeit-Filtering (<code>logmask</code>) greift ausschließlich für den DLT-Nachrichtenpfad. ARTI filtert eigenständig über <code>msg_id</code>.\n</li><li><strong>Performance &amp; Dead-Code-Elimination:</strong> Die Filterbedingung <code>(0 == msg_id.mstp_mtin &amp; logmask)</code> erfolgt strikt vor <code>buildDltMessage()</code>. Dadurch wird teure Serialisierung, Puffer-Allokation oder String-Formatierung für deaktivierte Log-Ebenen vollständig vermieden (Early Exit).\n</li></ul>"}, {"id": "FIG-4f1899d71f735434", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Programmablaufplan / Aktivitätsdiagramm (Control Flow Diagram) mit Differenzierung zwischen Compile-Time- und Runtime-Entscheidungsebenen.\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Functional Cluster <code>Log and Trace</code> (<code>ara::log</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung des internen Kontroll- und Filterflusses beim Absetzen eines Log-/Trace-Aufrufs (<code>logger.Log</code>). Visualisiert wird die Verzweigung zwischen dem klassischen DLT-Pfad (Diagnostic Log and Trace, Serialisierung &amp; IPC/Sink) und der ARTI-Schnittstelle (AUTOSAR Run-Time Interface für Tracing/Profiling) unter Berücksichtigung statischer C++-Template-Spezialisierung und dynamischer Filtermasken.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Funktionseinheiten:</strong>\n<ul class=\"fig-list\"><li><code>logger.Log(msg_id, params)</code>: Öffentliche C++-API-Einstiegsfunktion des Loggers.\n</li><li><code>TraceSwitch</code>: Statische Compile-Time-Verzweigung via C++-Template-Spezialisierung.\n</li><li><code>loggerimpl.Log(msg_id, params)</code>: Interne Laufzeit-Implementierungsklasse der Logging-Engine (blauer Bereich).\n</li><li><code>TraceArti</code>: ARTI-Trace-Hook / Backend-Schnittstelle zur Erfassung von Timing- und Laufzeitdaten ohne vorherige DLT-Filterung.\n</li><li><code>buildDltMessage()</code>: Serialisierungs-Engine zur Generierung der standardisierten DLT-Nachrichtenstruktur (Standard/Extended Header, Payload).\n</li><li><code>sendDltMessageToSink()</code>: IPC-/Transport-Abstraktion zum Versenden der DLT-PDU an den DLT-Daemon oder direkt an eine konfigurierte Log-Senke (z. B. Konsole, Dateisystem, Netzwerk/SOME/IP).\n</li><li><code>end</code>: Terminierung des Logging-Aufrufs.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Kontrollvariablen:</strong>\n<ul class=\"fig-list\"><li><code>msg_id</code>: Nachrichtenidentifikator, enthält u. a. das Bitfeld <code>mstp_mtin</code> (DLT Message Type &amp; Message Type Info: Log-Level bzw. Trace-Subtyp).\n</li><li><code>params</code>: Variadische Nutzdaten / Log-Argumente.\n</li><li><code>DltLogSink.category</code>: Kategorie der Ziel-Log-Senke (Gegenprüfung auf Konstante/Enumerator <code>DLT_LOGSINK_ARTI</code>).\n</li><li><code>logmask</code>: Konfigurierte Bitmaske der aktiven Log-Level bzw. Trace-Typen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>API-Aufruf (Synchron):</strong> Die Applikation ruft <code>logger.Log(msg_id, params)</code> auf.\n</li><li><strong>Compile-Time-Evaluation (<code>TraceSwitch</code>):</strong>\n<ul class=\"fig-list\"><li><em>Zweig „No“:</em> Direkte Ausleitung an <code>TraceArti</code>. Umgeht zur Compile-Zeit die Laufzeit-Logger-Engine vollständig (Zero-Overhead-Pfad).\n</li><li><em>Zweig „Yes“:</em> Weiterleitung an die Laufzeit-Instanz <code>loggerimpl.Log(msg_id, params)</code>.\n</li></ul>\n</li><li><strong>Evaluation Senken-Kategorie (<code>DLT_LOGSINK_ARTI == DltLogSink.category?</code>):</strong>\n<ul class=\"fig-list\"><li><em>Zweig „Yes“:</em> Verzweigt vor der DLT-Filterung direkt zu <code>TraceArti</code>. Die Filterung erfolgt in ARTI autonom auf Basis der <code>msg_id</code>.\n</li><li><em>Zweig „No“:</em> Eintritt in die DLT-Verarbeitungskette.\n</li></ul>\n</li><li><strong>DLT-Laufzeit-Filterung:</strong>\n<ul class=\"fig-list\"><li>Bedingung: <code>(0 == msg_id.mstp_mtin &amp; logmask)</code>\n</li><li><em>Evaluation <code>true</code> (Ergebnis 0):</em> Die Nachricht ist durch die Bitmaske maskiert/inaktiv → Sprung zu <code>end</code> (Drop/Frühzeitiger Abbruch ohne Payload-Generierung).\n</li><li><em>Evaluation <code>false</code> (Schnittmenge vorhanden):</em> Die Nachricht ist aktiv.\n</li></ul>\n</li><li><strong>Nachrichtenkonstruktion &amp; Dispatch:</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>buildDltMessage()</code> zur Formatierung der DLT-Frames.\n</li><li>Aufruf von <code>sendDltMessageToSink()</code> zur Weiterleitung an das Backend.\n</li><li>Terminierung bei <code>end</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Compile-Time-Optimierung (<code>TraceSwitch</code>):</strong> Durch Template-Spezialisierung kann der Trace-Pfad deterministisch fest verdrahtet werden. Entwickler müssen sicherstellen, dass bei aktivierten Low-Overhead-Traces keine unnötige Instanziierung von <code>loggerimpl</code> erfolgt.\n</li><li><strong>Separater ARTI-Filterpfad:</strong> ARTI-Meldungen dürfen <strong>nicht</strong> durch die DLT-Logmaske gefiltert werden. Das DLT-Laufzeit-Filtering (<code>logmask</code>) greift ausschließlich für den DLT-Nachrichtenpfad. ARTI filtert eigenständig über <code>msg_id</code>.\n</li><li><strong>Performance &amp; Dead-Code-Elimination:</strong> Die Filterbedingung <code>(0 == msg_id.mstp_mtin &amp; logmask)</code> erfolgt strikt vor <code>buildDltMessage()</code>. Dadurch wird teure Serialisierung, Puffer-Allokation oder String-Formatierung für deaktivierte Log-Ebenen vollständig vermieden (Early Exit).\n</li></ul>"}], "trans": [{"from": "FIG-5aae5d00cd13c25e", "to": "FIG-4f1899d71f735434", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Entscheidungsraute vor DLT-Filterung:</strong> Die Prüfbedingung <code>kARTI == logTraceLogMode?</code> wurde durch <code>DLT_LOGSINK_ARTI == DltLogSink.category?</code> ersetzt. Die Weiterleitung an <code>TraceArti</code> wird damit nicht mehr über den Betriebsmodus <code>logTraceLogMode</code> gegen <code>kARTI</code> gesteuert, sondern über die Kategorie der konfigurierten Senke (<code>DltLogSink.category</code>) gegen die Konstante <code>DLT_LOGSINK_ARTI</code>.\n</li></ul>"}]};
